const slaces=[{id:'everyday',name:'日常小事俱乐部',subtitle:'把普通的一天，变成值得分享的 Slice。',about:'散步、做饭、生活里的小发现。这里不需要宏大的主题，记录一个真实的小瞬间就好。',members:['小禾','阿宁的饭桌'],posts:['daily-walk','daily-dinner'],color:'#f1e6d8',mark:'☺'},{id:'curiosity',name:'好奇心实验室',subtitle:'一起动手，试试世界的另一种可能。',about:'分享科学实验、模拟和可玩的想法。把问题变成一个 Slice，让其他成员也能亲手探索。',members:['Kepler Lab','Almost Physics','Little Worlds'],posts:['orbit','wave','city'],color:'#e4ead8',mark:'✳'}];
const membershipData=readStored('slice-slace-membership-v1',[]);let joinedSlaces=new Set(Array.isArray(membershipData)?membershipData.filter(id=>slaces.some(s=>s.id===id)):[]);let currentSlace='everyday';
const slacePage=document.createElement('main');slacePage.id='slace-page';slacePage.hidden=true;followingPage.after(slacePage);
function slaceCards(list){return list.map(w=>`<article class="card following-feed-card"><div class="following-byline"><span class="following-avatar">${escapeHtml(w.author.slice(0,1))}</span><div><strong>${escapeHtml(w.author)}</strong><small>Space 成员 · ${escapeHtml(w.time)}</small></div></div><h3>${escapeHtml(w.title)}</h3><p>${escapeHtml(w.desc)}</p>${stage(w)}<div class="card-actions"><button data-like="${w.id}" aria-pressed="${likes.has(w.id)}">${likes.has(w.id)?'♥':'♡'} ${w.likes+(likes.has(w.id)?1:0)}</button><button data-share="${w.id}">↗ Share</button><button data-save="${w.id}" aria-pressed="${libraryIds.has(w.id)}">${libraryIds.has(w.id)?'✓ 已收藏':'＋ Library'}</button><button data-open="${w.id}">打开 Slice ↗</button></div></article>`).join('')}
function renderSlace(){const s=slaces.find(x=>x.id===currentSlace),joined=joinedSlaces.has(s.id),list=works.filter(w=>w.slaceId===s.id||s.posts.includes(w.id));slacePage.innerHTML=`<div class="slace-heading"><div><span class="eyebrow">SPACES FOR SHARED CURIOSITY</span><h1>Space</h1><p>Slicer 相聚的社区空间，Slice 在这里发生。</p></div><span class="slace-prototype">社区原型 · 本机保存</span></div><div class="slace-switch" role="group" aria-label="选择 Space">${slaces.map(x=>`<button data-slace="${x.id}" aria-pressed="${x.id===s.id}">${x.mark} ${x.name}${joinedSlaces.has(x.id)?' · 已加入':''}</button>`).join('')}</div><section class="slace-cover" style="background:${s.color}"><div class="slace-emblem">${s.mark}</div><div><span>SPACE / ${s.id.toUpperCase()}</span><h2>${s.name}</h2><p>${s.subtitle}</p><small>${s.members.length+(joined?1:0)} 位成员 · ${list.length} 个 Slice</small></div><div class="slace-cover-actions"><button class="dark" data-slace-join>${joined?'已加入 ✓ · 退出空间':'＋ 加入 Slace'}</button><button data-slace-publish ${joined?'':'disabled'}>＋ 在这里发布 Slice</button></div></section><div class="following-feed-layout"><section class="following-stream"><div class="slace-stream-title"><h3>空间里的 Slice</h3><span>成员发布</span></div>${slaceCards(list)||'<div class="following-feed-empty">还没有 Slice，发布第一个小发现吧。</div>'}</section><aside class="following-feed-aside"><h3>关于这个 Slace</h3><p>${s.about}</p><h3>空间成员</h3>${s.members.map(a=>`<div class="followed-person"><span class="following-avatar">${escapeHtml(a.slice(0,1))}</span><span>${escapeHtml(a)} <small>Slicer</small></span></div>`).join('')}${joined?'<div class="followed-person"><span class="following-avatar">我</span><span>你 <small>已加入</small></span></div>':''}<div class="slace-rules"><strong>在这里分享</strong><p>发布与空间主题相关的 Slice，尊重彼此的表达。加入空间后即可发布。</p></div><p class="following-local-note">示例空间与成员。加入状态和新发布的 Slice 仅保存在当前浏览器，暂不支持多人实时同步。</p></aside></div>`;initStages(slacePage)}
function syncSlaceRoute(){const match=location.hash.match(/^#slace(?:\/([a-z]+))?$/);slacePage.hidden=!match;if(!match)return;if(match[1]&&slaces.some(s=>s.id===match[1]))currentSlace=match[1];document.querySelector('main#discover').hidden=true;followingPage.hidden=true;document.querySelectorAll('header nav a').forEach(a=>{a.classList.toggle('current',a.id==='slace-link');if(a.id==='slace-link')a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});renderSlace()}
const slaceField=document.createElement('label');slaceField.className='slace-publish-field';slaceField.innerHTML='发布到 <select name="slaceDestination"><option value="">个人 Slice（不加入空间）</option></select><small>只有加入的 Slace 才能发布；Slice 也会出现在发现 Feed。</small>';document.querySelector('.publish-fields').prepend(slaceField);
function updateSlaceOptions(value=''){publishForm.elements.slaceDestination.innerHTML='<option value="">个人 Slice（不加入空间）</option>'+slaces.filter(s=>joinedSlaces.has(s.id)).map(s=>`<option value="${s.id}">${s.name} · Slace</option>`).join('');publishForm.elements.slaceDestination.value=joinedSlaces.has(value)?value:''}
const preSlaceCreator=openCreator;openCreator=function(work){preSlaceCreator(work);updateSlaceOptions((work||readStored(draftKey,null))?.slaceId||'')};
const preSlaceForm=formData;formData=function(){return {...preSlaceForm(),slaceId:publishForm.elements.slaceDestination.value}};
const preSlacePublish=publishForm.onsubmit;publishForm.onsubmit=e=>{const id=publishForm.elements.slaceDestination.value;if(id&&!joinedSlaces.has(id)){e.preventDefault();document.querySelector('#publish-error').textContent='请先加入这个 Slace。';return}preSlacePublish(e);if(!publishDialog.open&&id){currentSlace=id;location.hash='slace/'+id;renderSlace();window.scrollTo({top:0,behavior:'smooth'});toast('已发布到 '+slaces.find(s=>s.id===id).name+' · 本机保存')}};
slacePage.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.slace){location.hash='slace/'+b.dataset.slace}if(b.hasAttribute('data-slace-join')){const next=new Set(joinedSlaces);next.has(currentSlace)?next.delete(currentSlace):next.add(currentSlace);try{localStorage.setItem('slice-slace-membership-v1',JSON.stringify([...next]))}catch{toast('无法保存加入状态，请检查浏览器存储');return}joinedSlaces=next;renderSlace();updateSlaceOptions();toast(next.has(currentSlace)?'已加入 Slace，现在可以发布 Slice':'已退出 Slace，已发布的 Slice 仍然保留')}if(b.hasAttribute('data-slace-publish')&&joinedSlaces.has(currentSlace)){openCreator();updateSlaceOptions(currentSlace)}});
const preSlaceRender=render;render=function(){preSlaceRender();if(!slacePage.hidden)renderSlace()};
window.addEventListener('hashchange',syncSlaceRoute);updateSlaceOptions();syncSlaceRoute();
